import{_ as r}from"./chunks/45.DDoa-c4v.js";import{_ as s}from"./chunks/1._Wu06lVH.js";import{_ as i}from"./chunks/0.xVPDiwtD.js";import{_ as l}from"./chunks/2.9ug2zROR.js";import{_ as c}from"./chunks/11.DiIhyeL-.js";import{_ as e}from"./chunks/0.B7TrDeTt.js";import{_ as d}from"./chunks/12.D1pIPcbk.js";import{_ as h}from"./chunks/13.eUzjeEIF.js";import{_ as p}from"./chunks/1.BU1qyW7B.js";import{_ as o}from"./chunks/0.DyB7G7H5.js";import{_ as g}from"./chunks/3.PcdR27wg.js";import{_ as m}from"./chunks/4.ZpmvUIOM.js";import{_ as u}from"./chunks/100.DMbJtyMU.js";import{_ as b}from"./chunks/community.BdKwbEUF.js";import{_ as y,C as _,o as f,c as w,ak as a,E as v}from"./chunks/framework.sbZkgmEx.js";const x="/projects/AiBlock/en/advanced-kit/assets/1.DY-yICSK.webp",k="/projects/AiBlock/en/advanced-kit/assets/2.1.spV0OpNX.webp",P="/projects/AiBlock/en/advanced-kit/assets/2.CsRwh8A0.webp",q="/projects/AiBlock/en/advanced-kit/assets/3.BEY_mZ9J.webp",z="/projects/AiBlock/en/advanced-kit/assets/4.Q7SKcshR.webp",J=JSON.parse('{"title":"3.45 Mecha Dinosaur","description":"","frontmatter":{},"headers":[],"relativePath":"docs/3.Creative Builds/3.45 Mecha Dinosaur.md","filePath":"docs/3.Creative Builds/3.45 Mecha Dinosaur.md"}'),j={name:"docs/3.Creative Builds/3.45 Mecha Dinosaur.md"};function C(T,t,A,S,B,D){const n=_("Pdf");return f(),w("div",null,[t[0]||(t[0]=a('<h1 id="_3-45-mecha-dinosaur" tabindex="-1">3.45 Mecha Dinosaur <a class="header-anchor" href="#_3-45-mecha-dinosaur" aria-label="Permalink to &quot;3.45 Mecha Dinosaur&quot;">​</a></h1><h2 id="_3-45-1-lesson-introduction" tabindex="-1">3.45.1 Lesson Introduction <a class="header-anchor" href="#_3-45-1-lesson-introduction" aria-label="Permalink to &quot;3.45.1 Lesson Introduction&quot;">​</a></h2><p>Focusing on a bionic mecha dinosaur robot, this lesson explores coordinated programming among a motor, a servo, and an ultrasonic sensor. It achieves a biomimetic routine that detects obstacles, advances automatically, and opens its jaws. The content illustrates bipedal walking mechanics alongside dual-actuator synchronized control. It reinforces distance threshold triggering logic. Furthermore, it examines core robotics concepts of integrating sensory modules to enable autonomous behavioral decisions.</p><img loading="lazy" height="1662" width="1662" src="'+r+'" class="common_img" style="width:400px;"><h2 id="_3-45-2-learning-objectives" tabindex="-1">3.45.2 Learning Objectives <a class="header-anchor" href="#_3-45-2-learning-objectives" aria-label="Permalink to &quot;3.45.2 Learning Objectives&quot;">​</a></h2><ol><li><p><strong>Knowledge Objectives</strong>: Understand dynamic balance principles in bipedal locomotion, recognizing pendulum-style alternating step mechanisms. Master single-motor power distribution transmissions that drive dual legs. Consolidate ultrasonic distance measurement and threshold triggering control logic.</p></li><li><p><strong>Skill Objectives</strong>: Assemble the mechanical structure of the bipedal dinosaur independently, mastering servo zero-point calibration during installation. Construct synchronized control routines coordinating motor rotation with servo oscillation. Implement an integrated routine where ultrasonic obstacle detection triggers autonomous walking and jaw actuation.</p></li><li><p><strong>Thinking Objectives</strong>: Build system thinking centered on multi-actuator synchronized control, and understand coordinated multi-channel output programming. Cultivate engineering design awareness for dynamic physical balance. Reinforce intelligent control methodologies where sensory perception triggers automated behavioral responses.</p></li><li><p><strong>Application Objectives</strong>: Connect concepts to practical applications including bipedal walkers, humanoid robots, and autonomous obstacle-avoidance systems. Appreciate the value of biomimetic robotics across educational, entertainment, and industrial sectors. Inspire interdisciplinary interest spanning paleontology, biomechanics, and robotics technology.</p></li></ol><h2 id="_3-45-3-preparation" tabindex="-1">3.45.3 Preparation <a class="header-anchor" href="#_3-45-3-preparation" aria-label="Permalink to &quot;3.45.3 Preparation&quot;">​</a></h2><h3 id="_1-hardware-preparation" tabindex="-1">(1) Hardware Preparation <a class="header-anchor" href="#_1-hardware-preparation" aria-label="Permalink to &quot;(1) Hardware Preparation&quot;">​</a></h3><ul><li><p>AiBlock controller</p></li><li><p>360° block motor</p></li><li><p>180° block servo</p></li><li><p>Ultrasonic sensor</p></li><li><p>Building block parts pack</p></li><li><p>Type-C data cable</p></li><li><p>Assembly manual</p></li><li><p>Computer</p></li></ul><h3 id="_2-software-preparation" tabindex="-1">(2) Software Preparation <a class="header-anchor" href="#_2-software-preparation" aria-label="Permalink to &quot;(2) Software Preparation&quot;">​</a></h3><ul><li>WonderLab graphical programming platform</li></ul><h2 id="_3-45-4-hands-on-project" tabindex="-1">3.45.4 Hands-On Project <a class="header-anchor" href="#_3-45-4-hands-on-project" aria-label="Permalink to &quot;3.45.4 Hands-On Project&quot;">​</a></h2><h3 id="_1-project-analysis" tabindex="-1">(1) Project Analysis <a class="header-anchor" href="#_1-project-analysis" aria-label="Permalink to &quot;(1) Project Analysis&quot;">​</a></h3><p>The core project of this lesson is the Mecha Dinosaur, achieving a biomimetic predation behavior where target detection triggers synchronized walking and jaw actuation. The system adopts an architecture combining ultrasonic perception with dual-actuator coordinated response. The ultrasonic sensor continuously scans ahead, triggering active behavior when obstacle distance drops below 15 cm. The actuation layer manages two outputs: a motor drives dual legs through a split gear train to execute alternating steps using dynamic balance, while a servo cycles jaw angles between 0° and 30° to simulate opening and closing. Both outputs start and halt concurrently to maintain synchronized behavior. Built-in RGB LEDs on the ultrasonic sensor illuminate red as an alert indicator, enhancing visual feedback and simulating an active predatory response.</p><h3 id="_2-assembly-guide" tabindex="-1">(2) Assembly Guide <a class="header-anchor" href="#_2-assembly-guide" aria-label="Permalink to &quot;(2) Assembly Guide&quot;">​</a></h3>',15)),v(n,{src:"../../_static/shared/pdf/chapter_3/45.pdf"}),t[1]||(t[1]=a('<h3 id="_3-hardware-wiring" tabindex="-1">(3) Hardware Wiring <a class="header-anchor" href="#_3-hardware-wiring" aria-label="Permalink to &quot;(3) Hardware Wiring&quot;">​</a></h3><ul><li><p>Connect the 360° block motor to port <strong>S1</strong> of the controller using a 3-pin servo cable.</p></li><li><p>Connect the 180° block servo to port <strong>S2</strong> of the controller using a 3-pin servo cable.</p></li><li><p>Connect the ultrasonic sensor to port <strong>A</strong> of the controller using a 4-pin module cable.</p></li></ul><img loading="lazy" height="1540" width="2430" src="'+x+'" class="common_img" style="width:500px;"><h3 id="_4-adding-extensions" tabindex="-1">(4) Adding Extensions <a class="header-anchor" href="#_4-adding-extensions" aria-label="Permalink to &quot;(4) Adding Extensions&quot;">​</a></h3><ul><li>Select <strong>Ultrasonic sensor</strong> under the <strong>Input Module</strong> category.</li></ul><img loading="lazy" height="1040" width="1920" src="'+k+'" class="common_img" style="width:800px;"><ul><li>Select <strong>180° servo</strong> and <strong>360° Motor</strong> under the <strong>Motion module</strong> category.</li></ul><img loading="lazy" height="1040" width="1920" src="'+P+'" class="common_img" style="width:800px;"><h3 id="_5-core-blocks" tabindex="-1">(5) Core Blocks <a class="header-anchor" href="#_5-core-blocks" aria-label="Permalink to &quot;(5) Core Blocks&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:center;">Block</th><th style="text-align:center;">Category</th><th style="text-align:left;">Description</th></tr></thead><tbody><tr><td style="text-align:center;"><img loading="lazy" height="121" width="358" src="'+s+'"></td><td style="text-align:center;"><img loading="lazy" height="71" width="77" src="'+i+'"></td><td style="text-align:left;">Serve as the main program loop container, continuously executing internal code after power-on initialization.</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="111" width="360" src="'+l+'"></td><td style="text-align:center;"><img loading="lazy" height="71" width="77" src="'+i+'"></td><td style="text-align:left;">Execute only once after startup to initialize hardware configurations and system parameters.</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="89" width="495" src="'+c+'"></td><td style="text-align:center;"><img loading="lazy" height="53" width="80" src="'+e+'"></td><td style="text-align:left;">Initialize the hardware connection port for the ultrasonic sensor.</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="112" width="658" src="'+d+'"></td><td style="text-align:center;"><img loading="lazy" height="53" width="80" src="'+e+'"></td><td style="text-align:left;">Retrieve obstacle distance data measured by the ultrasonic sensor in centimeters (cm).</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="113" width="953" src="'+h+'"></td><td style="text-align:center;"><img loading="lazy" height="53" width="80" src="'+e+'"></td><td style="text-align:left;">Control onboard RGB lights of the ultrasonic module to illuminate in preset colors, with options to control 1, 2, or all LEDs.</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="145" width="655" src="'+p+'"></td><td style="text-align:center;"><img loading="lazy" height="71" width="80" src="'+o+'"></td><td style="text-align:left;">Drive the 360° block motor at a designated port to rotate continuously at a customized speed in the forward or reverse direction.</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="91" width="416" src="'+g+'"></td><td style="text-align:center;"><img loading="lazy" height="71" width="80" src="'+o+'"></td><td style="text-align:left;">Stop power output to the 360° block motor at the designated port, immediately halting motor rotation.</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="88" width="708" src="'+m+'"></td><td style="text-align:center;"><img loading="lazy" height="71" width="80" src="'+o+'"></td><td style="text-align:left;">Control the 180° block servo at the designated port to rotate for a specified duration at a customized speed. In non-blocking mode, the program proceeds immediately to subsequent blocks without waiting for motion completion.</td></tr></tbody></table><h3 id="_6-program-description-and-upload" tabindex="-1">(6) Program Description and Upload <a class="header-anchor" href="#_6-program-description-and-upload" aria-label="Permalink to &quot;(6) Program Description and Upload&quot;">​</a></h3><ul><li>Program Schematic</li></ul><img loading="lazy" height="490" width="430" src="'+q+'" class="common_img" style="width:400px;"><ul><li><p>Complete Program</p><p>Upon startup, the program initializes the hardware port for the ultrasonic sensor and sets its onboard RGB lights to red. The main loop continuously checks whether an obstacle is detected within 15 cm. When an obstacle is detected, motor S1 reverses at 20% speed to drive forward locomotion while servo S2 cycles periodically between opening and closing the jaws. When no obstacle is detected, both the motor and servo stop operating.</p></li></ul><img loading="lazy" height="750" width="630" src="'+z+'" class="common_img" style="width:500px;"><ul><li><p>Program Upload</p><p>Following the animation, click <strong>Connect device</strong>, select the serial port, then click the upload button to complete the program transfer and test the execution results.</p></li></ul><img loading="lazy" height="360" width="640" src="'+u+'" class="common_img" style="width:800px;"><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>The source files are available for download under <a href="https://drive.google.com/drive/folders/1adJTOnyve2MmEehrB9YFSW8echTWwoF2?usp=sharing" target="_blank" rel="noreferrer">Program Files</a>.</strong></p></div><h2 id="_3-45-5-expansion-and-challenge" tabindex="-1">3.45.5 Expansion and Challenge <a class="header-anchor" href="#_3-45-5-expansion-and-challenge" aria-label="Permalink to &quot;3.45.5 Expansion and Challenge&quot;">​</a></h2><p><strong>Project 1: Multi-Tier Status Indicator System</strong></p><p>Illuminate green LEDs during standby to indicate a clear environment, switch to solid red when distance drops below 15 cm, and flash red rapidly when obstacles are within 5 cm. Program locomotion speed and jaw cycling frequency to increase proportionally as obstacle distance decreases. Practice multi-tier threshold evaluation and multi-state synchronized outputs while exploring tiered response control strategies. Extend discussions to traffic signal management, industrial status towers, and human-robot interaction indicators.</p><p><strong>Project 2: Interactive Motion-Expressive Dinosaur</strong></p><p>Incorporate a third servo to control tail sway, triggering synchronized locomotion, jaw biting, tail wagging, and buzzer sound effects upon obstacle detection. Practice multi-servo coordination and multi-actuator synchronization while understanding coordinated programming architectures. Extend discussions to multi-joint coordination in humanoid robotics and expressive animatronics in entertainment robotics.</p><h2 id="_3-45-6-q-a" tabindex="-1">3.45.6 Q&amp;A <a class="header-anchor" href="#_3-45-6-q-a" aria-label="Permalink to &quot;3.45.6 Q&amp;A&quot;">​</a></h2><p><strong>Question 1: Why does the mecha dinosaur remain upright on only two legs without falling, and what is the principle of bipedal walking balance?</strong></p><p>Answer: Bipedal locomotion relies on <strong>dynamic balance</strong>, operating similarly to an inverted pendulum. While walking, the two legs function alternately: one leg contacts the ground as a supporting pillar bearing total body weight, while the opposite leg swings forward like a pendulum to prepare for the subsequent footfall. Because leg alternation occurs in rapid succession, the center of mass continuously shifts above the shifting support polygon without tipping over. The mecha dinosaur in this lesson also features broad footpads and a low center of gravity, which further enhances structural stability. Real humans, birds, and theropod dinosaurs walk using this exact mechanism, maintaining dynamic equilibrium through continuous stepping rather than static positioning. Advanced bipedal robots incorporate internal gyroscope sensors and high-frequency algorithms to adjust center-of-mass positioning continuously. The dinosaur in this lesson achieves this behavior through a simplified, mechanically coupled bipedal linkage.</p><p><strong>Question 2: Why does the model employ a servo for jaw actuation but a standard motor for leg locomotion, and what are their respective characteristics?</strong></p><p>Answer: The two mechanisms require fundamentally different motion control profiles. <strong>Jaw movement</strong> demands precise angular positioning. Opening angles, closing limits, and static holding positions must be strictly controlled, which directly matches the closed-loop positional capabilities of servos. <strong>Leg locomotion</strong> requires continuous, uninterrupted rotational torque. Driving the leg linkage through gears requires ongoing rotation where velocity and direction matter rather than holding a specific angle, making a continuous-rotation 360° block motor the appropriate selection. In summary, applications demanding precise angular positioning rely on servos, whereas tasks requiring continuous mechanical propulsion utilize standard motors. Complex robotic systems routinely deploy diverse actuator types matched to specific kinematic needs, utilizing servos for articulated joints, standard motors for wheeled drive chassis, and high-speed motors for cooling fans.</p><h2 id="_3-45-7-technical-support-and-product-discussion" tabindex="-1">3.45.7 Technical Support and Product Discussion <a class="header-anchor" href="#_3-45-7-technical-support-and-product-discussion" aria-label="Permalink to &quot;3.45.7 Technical Support and Product Discussion&quot;">​</a></h2><p>Submit questions or share project modifications in the community forum:</p><a href="https://forum.hiwonder.com.cn/" target="_blank" rel="noopener noreferrer"><img loading="lazy" height="640" width="1136" src="'+b+'" class="common_img" style="width:800px;"></a>',31))])}const K=y(j,[["render",C]]);export{J as __pageData,K as default};
